B=pathlib.Path(__file__).resolve().parents[1];O=B/'intermediate/codex';rows=[json.loads(l) for l in (O/'deep-read-evidence.jsonl').open()]
def ev(sid,line,role):
 r=next(r for r in rows if sid in r['source_path'] and r['line']==line and r['role']==role)
 return {k:r[k] for k in ['source_path','line','timestamp','role','text']}
