out=[];md=['# Codex 近 30 天代表性任务链深读','', '这是全量扫描后的目的性深读，覆盖 15 个根任务标识、12 条主要任务链；不是随机样本，不用于推算全体失败率。原话与 AI 自报结果分别标明；没有将历史 AI 结论直接升级为今日代码事实。','']
for key,title,refs,obs,change,result in cases:
 es=[ev(*r) for r in refs];out.append({'case_id':key,'title':title,'observation':obs,'improvement':change,'visible_outcome_and_limit':result,'evidence':es})
 md += ['## '+key+' '+title,'',obs,'','**可改进：** '+change,'','**结果边界：** '+result,'','证据：','']
 for e in es:
  q=e['text'].replace('\n',' ')[:240];md.append(f"- {e['timestamp']} · {e['role']} · [{pathlib.Path(e['source_path']).name}:{e['line']}]({e['source_path']}:{e['line']})：{q}")
 md.append('')
